mapping.statement:
SELECT
    id,
    internal_resource_id,
    hardware_security_module_id,
    application_id,
    slot,
    pin,
    configuration,
    creation_date,
    last_update,
    resource_version
FROM
    cfg_hardware_security_module_slot
{{ if .FilterGroup }}
    WHERE
    {{ range $counter, $filter := .FilterGroup.Filters }}
        {{ if lt $counter 1}}
            {{$filter.ToSQLStmt}}
        {{ else }}
            AND {{$filter.ToSQLStmt}}
        {{ end }}
    {{end}}
{{ end }}
{{ if .Order }}
    ORDER BY {{ .Order.ToSQLStmt }}
{{ end }}
{{ if .Pagination}}
    LIMIT {{.Pagination.Limit}} OFFSET {{.Pagination.Offset}}
{{ end }}
